// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(new Log()));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        uint256 min = c.MinDeposit();
        vm.assume(amount >= min);
        vm.assume(amount <= 1e30);
        vm.deal(actor, amount);

        uint256 beforeBal = c.balances(actor);

        vm.prank(actor);
        try c.Deposit{value: amount}() {
            uint256 afterBal = c.balances(actor);
            assertTrue(afterBal == beforeBal + amount);
        } catch {
            assertTrue(c.balances(actor) == beforeBal);
        }
    }
}
